import {test} from 'node:test';
import assert from 'node:assert/strict';
import {createHash} from 'node:crypto';
import {portableSha256,calculateVisualAssetContentHash,inspectManagedGltfAsset,createMesAssetGateway,listManagedTextureAssetRequirements,normalizeCatalog,seedDocument,applyCatalog} from './dist/engine.mjs';
const bytes=value=>Uint8Array.from(Buffer.from(value)).buffer;
const hash=value=>'sha256:'+createHash('sha256').update(Buffer.from(value)).digest('hex');
const gltf={asset:{version:'2.0'},nodes:[{mesh:0}],meshes:[{primitives:[{attributes:{POSITION:0}}]}],accessors:[{count:3}],buffers:[{uri:'data:application/octet-stream;base64,AAAA'}]};
const inspect=async value=>{const raw=bytes(JSON.stringify(value));return inspectManagedGltfAsset({bytes:raw,expectedContentHash:hash(raw)});};
test('Portable LAN SHA-256 matches native for empty, Unicode, padding boundaries and 1MiB',async()=>{for(const size of [0,1,55,56,63,64,65,1000000]){const raw=Uint8Array.from({length:size},(_,i)=>i%251).buffer;assert.equal(portableSha256(raw),hash(raw));assert.equal(await calculateVisualAssetContentHash(raw),hash(raw));}assert.equal(portableSha256(bytes('门窗资源')),hash(bytes('门窗资源')));});
test('Hash helper works without SubtleCrypto on insecure LAN HTTP',async()=>{const descriptor=Object.getOwnPropertyDescriptor(globalThis,'crypto');Object.defineProperty(globalThis,'crypto',{value:undefined,configurable:true});try{assert.equal(await calculateVisualAssetContentHash(bytes('abc')),hash(bytes('abc')));}finally{Object.defineProperty(globalThis,'crypto',descriptor);}});
test('Valid embedded glTF inspection retains exact hash and triangle budget',async()=>{const result=await inspect(gltf);assert.equal(result.estimatedTriangleCount,1);assert.equal(result.nodeCount,1);});
test('External URIs including extension URIs, wrong version/count/index are rejected',async()=>{for(const value of [{...gltf,asset:{version:'1.0'}},{...gltf,extensions:{foo:{uri:'http://remote.invalid/a'}}},{...gltf,buffers:[{uri:'other.bin'}]},{...gltf,accessors:[{count:-1}]},{...gltf,meshes:[{primitives:[{attributes:{POSITION:99}}]}]}])await assert.rejects(()=>inspect(value));});
test('GLB complete aligned chunks accepted; truncated trailing chunks rejected',async()=>{const json=Buffer.from(JSON.stringify(gltf));const padded=Buffer.alloc(Math.ceil(json.length/4)*4,32);json.copy(padded);const file=Buffer.alloc(20+padded.length);file.writeUInt32LE(0x46546c67,0);file.writeUInt32LE(2,4);file.writeUInt32LE(file.length,8);file.writeUInt32LE(padded.length,12);file.writeUInt32LE(0x4e4f534a,16);padded.copy(file,20);const raw=bytes(file);assert.equal((await inspectManagedGltfAsset({bytes:raw,expectedContentHash:hash(raw)})).meshCount,1);const malformed=Buffer.concat([file,Buffer.alloc(3)]);malformed.writeUInt32LE(malformed.length,8);const bad=bytes(malformed);await assert.rejects(()=>inspectManagedGltfAsset({bytes:bad,expectedContentHash:hash(bad)}));});
test('MES gateway uses envelope/grant and refuses replaced read bytes',async()=>{const raw=bytes(JSON.stringify(gltf)),id='ASSET-TEST',contentHash=hash(raw);const descriptor={assetId:id,kind:'component-model',mediaType:'model/gltf+json',contentHash,byteLength:raw.byteLength,storedAtIso:new Date().toISOString()};let corrupt=false;const calls=[];
 const transport=async(path,init={})=>{calls.push([path,init.method]);if(path.startsWith('/content?'))return new Response(corrupt?bytes('{}'):raw,{headers:{'Content-Type':'model/gltf+json'}});return Response.json({code:0,data:path==='/authorize'?{grantId:'grant'}:path.startsWith('/uploads/')?{asset:descriptor,inspection:{contentHash}}:descriptor});};
 const gateway=createMesAssetGateway(transport);await gateway.upload({assetId:id,expectedContentHash:contentHash,mediaType:descriptor.mediaType,bytes:raw,inspectedAtIso:descriptor.storedAtIso});assert.equal((await gateway.read(id,contentHash)).descriptor.assetId,id);assert.equal(calls[1][1],'PUT');corrupt=true;await assert.rejects(()=>gateway.read(id,contentHash));});
test('Texture selection and decimal repeat survive formal JSON roundtrip and reload discovery',()=>{const id='31d5ecce-031c-419b-bb7b-4d183bc55c8c';const first=seedDocument({designId:id,lineId:id,mark:'C1',quantity:1,widthMm:1200,heightMm:1500});const data=normalizeCatalog(id,2,{category:'finish',code:'TEXTURE',name:'木纹',specification:'颜色贴图',note:'',materialFamily:'metal',baseColor:'#ffffff',metalness:.3,roughness:.4,opacity:1,thicknessMm:null,compatibleProfileSystemIds:[],textureSetId:'MES-TEXTURE-TEST',textureContentHash:hash(bytes('abc')),textureRepeatX:.5,textureRepeatY:.75});const changed=applyCatalog(first,first.windows[0].objectId,'profile-outside',{id,revision:2,status:'PUBLISHED',data});assert.deepEqual(changed.windows[0].visualConfiguration.appearance.frame.outside.uvScale,{x:.5,y:.75});assert.equal(listManagedTextureAssetRequirements(changed).length,1);assert.throws(()=>normalizeCatalog(id,2,{...data,category:'finish',code:'INVALID'}));});
test('MES missing/forged envelopes fail closed',async()=>{const gateway=createMesAssetGateway(async()=>Response.json({code:403,msg:'无权限'}));await assert.rejects(()=>gateway.describe('ASSET'));});
